def find_frame_bounds(grid, color):
    """Find min/max bounds of a color that forms a rectangular frame"""
    cells = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color:
                cells.append((r, c))

    if not cells:
        return None

    min_r, max_r = min(c[0] for c in cells), max(c[0] for c in cells)
    min_c, max_c = min(c[1] for c in cells), max(c[1] for c in cells)

    # Check if this is a frame (border cells exist, some interior may be different)
    return min_r, max_r, min_c, max_c, len(cells), (max_r-min_r+1)*(max_c-min_c+1)

